mapper.select:
select ai.id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.business_hours, ai.seat_count, ai.is_release, ifnull(tc.cnt,0) total_seat_count, ifnull(tc.cnt,0) - ifnull(cc.cnt,0) free_seat_count from (select id, name, introduction, district_id, district_name, city_id, city_name, province_id, province_name, address_detail, latitude, longitude, phone, business_hours, seat_count, is_release from study_store
is_deleted = 0
and province_id = #{queryVo.provinceId}
and city_id = #{queryVo.cityId}
and district_id = #{queryVo.districtId}
) ai left join (select store_id, count(*) cnt from seat where is_deleted = 0 and is_release = 1 group by store_id) tc on ai.id = tc.store_id left join (select store_id, count(*) cnt from booking_order where is_deleted = 0 and status in (2, 5) group by store_id) cc on ai.id = cc.store_id
